function temporal(){
 const el=mount('temporal-lab','Elapsed time is independent of display zone',`<div class="controls">${label('Hospital episode','temporal-stay',D.hospital.map(h=>[h.hospital_stay_key,h.encounter_id]))}${label('Display time basis','temporal-zone',[['nepal','Nepal · UTC+05:45'],['utc','Canonical UTC']])}</div><div class="temporal-output"></div><div class="status" aria-live="polite"></div>`);
 const render=()=>{const h=D.hospital.find(x=>x.hospital_stay_key===Number($('.temporal-stay',el).value)),nepal=$('.temporal-zone',el).value==='nepal';const display=s=>nepal?s.replace('T',' '):new Date(s).toISOString().replace('T',' ');const hours=(new Date(h.discharged_at)-new Date(h.admitted_at))/3600000,days=(Date.parse(h.discharged_at.slice(0,10))-Date.parse(h.admitted_at.slice(0,10)))/86400000;
  $('.temporal-output',el).innerHTML=`<div class="timeline-labels"><div><b>Admission</b><br>${esc(display(h.admitted_at))}</div><div><b>Discharge</b><br>${esc(display(h.discharged_at))}</div></div><div class="timeline-track"><span class="timeline-point"></span><span class="timeline-line"></span><span class="timeline-point"></span></div><div class="metric-row"><div class="metric"><b>${fmt(hours)}</b><span>elapsed hours</span></div><div class="metric"><b>${fmt(hours/24)}</b><span>elapsed 24-hour days</span></div><div class="metric"><b>${days}</b><span>Nepal calendar boundaries</span></div><div class="metric"><b>+05:45</b><span>Nepal offset from UTC</span></div></div>`;
  $('.status',el).textContent=`${h.encounter_id}: changing the display time basis leaves the duration unchanged. Calendar-boundary days (${days}) and elapsed 24-hour days (${fmt(hours/24)}) measure different quantities. Date keys are grouping identifiers, not duration operands.`;
 };el.addEventListener('change',render);render();
}
function quality(){
 const cases={initial:{received:20,new:16,corrected:0,duplicates:2,rejected:1,pending:1},replay:{received:20,new:0,corrected:0,duplicates:18,rejected:1,pending:1},repaired:{received:2,new:2,corrected:0,duplicates:0,rejected:0,pending:0}};
 const el=mount('quality-lab','Account for every delivered row',`<div class="controls">${label('Synthetic batch','quality-case',[['initial','Initial submission'],['replay','Replay identical submission'],['repaired','Repair the two unresolved records']])}<button class="quality-reset" type="button">Reset dashboard</button></div><div class="quality-metrics metric-row"></div><div class="quality-table"></div><div class="status" aria-live="polite"></div><p class="hint">This batch scenario surrounds the 16-line teaching fixture. Rejected and pending envelopes are not extra clinical facts in the checked-in dataset. Repair is a separate two-envelope batch.</p>`);
 const render=()=>{const k=$('.quality-case',el).value,c=cases[k],total=c.new+c.corrected+c.duplicates+c.rejected+c.pending;$('.quality-metrics',el).innerHTML=[['Received',c.received],['Accepted new',c.new],['Duplicate delivery',c.duplicates],['Rejected / pending',c.rejected+c.pending]].map(([t,v])=>`<div class="metric"><b>${v}</b><span>${t}</span></div>`).join('');$('.quality-table',el).innerHTML=table([{received:c.received,accepted_new:c.new,accepted_corrections:c.corrected,duplicate_submissions:c.duplicates,rejected:c.rejected,pending:c.pending}]);$('.status',el).textContent=`✓ RECONCILED: ${c.received} = ${c.new} new + ${c.corrected} corrections + ${c.duplicates} duplicates + ${c.rejected} rejected + ${c.pending} pending (${total} accounted for). ${k==='replay'?'Idempotent replay adds zero new facts.':k==='repaired'?'The two repaired envelopes now pass validation; this scenario is separate from the immutable fixture.':'Matching counts are necessary; also reconcile amounts, source versions and completeness.'}`};el.addEventListener('change',render);$('.quality-reset',el).addEventListener('click',()=>{$('.quality-case',el).value='initial';render()});render();
}
function normalization(){
 const el=mount('normalization-lab','One catalog correction, several possible copies',`<p class="normalization-lab-note">These operational-style projections reuse the same 16 synthetic dispensing lines. The proposed Prescription tables illustrate organization; they do not add a prescribing dataset or infer unrecorded prescription times. All costs and counts remain tied to the supplied extract.</p><div class="controls">${label('View the arrangement','normalization-view',[['normalized','Normalized relational tables'],['flat','Flat redundant extract'],['star','Dimensional star'],['summary','Precomputed product summary']])}<button class="anomaly" type="button">Edit one copied product name</button><button class="catalog-fix" type="button">Apply governed catalog correction</button><button class="normalization-reset" type="button">Reset example</button></div><div class="status normalization-status" aria-live="polite"></div><div class="normalization-metrics metric-row"></div><div class="normalization-structure"></div><div class="normalization-query"></div>`);
 const originalNames=new Map(D.products.map(p=>[p.product_key,p.product_name]));
 let catalog=new Map(originalNames),flat=[],state='original';
 const makeFlat=()=>D.pharmacy.map(r=>({source_record_id:r.source_record_id,rx_id:r.prescription_id,line_no:1,client_id:lookup('clients','client_key',r.client_key).client_id,product_id:lookup('products','product_key',r.product_key).product_code,product_key:r.product_key,product_name:catalog.get(r.product_key),quantity:r.quantity,total_cost:r.total_cost}));
 flat=makeFlat();
 const changedName='Synthetic product A — revised catalog label';
 const render=()=>{
  const mode=$('.normalization-view',el).value,product1=D.pharmacy.filter(r=>r.product_key===1).length,distinctCopies=new Set(flat.filter(r=>r.product_key===1).map(r=>r.product_name)).size;
  const status=$('.normalization-status',el);status.classList.toggle('error',state==='anomaly');status.textContent=state==='anomaly'?`✕ UPDATE ANOMALY · Only ${D.pharmacy[0].source_record_id} has this edited copied name. The same product_id now has ${distinctCopies} descriptions across ${product1} flat copies. The normalized Product catalog still owns one consistent description: ${catalog.get(1)}. Numeric source records are unchanged.`:state==='governed'?`✓ GOVERNED CORRECTION · One owned Product value was corrected; joins now retrieve the revised description consistently. The flat extract was explicitly rebuilt so all ${product1} copied names agree. A flat table does not synchronize itself. Counts, quantities and known-cost totals are unchanged.`:'✓ ORIGINAL STATE · Product descriptions are owned by two catalog rows. The 16-line flat extract repeats those descriptions. Change only one copied name to expose the risk, then compare with a governed catalog correction.';
  const nameCells=mode==='flat'?16:mode==='summary'?0:D.products.length;
  $('.normalization-metrics',el).innerHTML=[['Input dispensing lines',16],['Owned product descriptions',2],['Stored product-name cells',nameCells],['Output rows',mode==='summary'?2:16]].map(([t,n])=>`<div class="metric"><b>${n}</b><span>${t}</span></div>`).join('');
  let structure='',sql='',rows=[];
  if(mode==='normalized'){
   const headers=D.pharmacy.map(r=>({rx_id:r.prescription_id,client_id:lookup('clients','client_key',r.client_key).client_id}));
   const lines=D.pharmacy.map(r=>({rx_id:r.prescription_id,line_no:1,product_id:lookup('products','product_key',r.product_key).product_code,quantity:r.quantity}));
   const products=D.products.map(p=>({product_id:p.product_code,product_name:catalog.get(p.product_key)}));
   const clients=D.clients.map(c=>({client_id:c.client_id,client_district:lookup('geography','geography_key',c.residence_geography_key).district}));
   structure=`<p>Primary and foreign keys connect four proposed relations. The same product name is stored once in Product, then retrieved for each line. The header and line previews show four of 16 rows.</p><div class="normalization-map">${[['PrescriptionHeader',headers.slice(0,4),'PK rx_id · FK client_id'],['PrescriptionLine',lines.slice(0,4),'PK (rx_id, line_no) · FK rx_id · FK product_id'],['Product',products,'PK product_id'],['Client',clients,'PK client_id']].map(([name,data,keys])=>`<div class="normalized-table"><h4><code>${name}</code></h4><p class="hint">${esc(keys)}</p>${table(data)}</div>`).join('')}</div>`;
   rows=makeFlat().map(r=>({rx_id:r.rx_id,line_no:r.line_no,client_id:r.client_id,product_name:r.product_name,quantity:r.quantity}));
   sql=`-- Proposed operational-style tables, not installed by the teaching scripts.\nSELECT h.rx_id, l.line_no, c.client_id, p.product_name, l.quantity\nFROM PrescriptionHeader h\nJOIN PrescriptionLine l ON l.rx_id = h.rx_id\nJOIN Product p ON p.product_id = l.product_id\nJOIN Client c ON c.client_id = h.client_id\nORDER BY h.rx_id, l.line_no;`;
  }else if(mode==='flat'){
   rows=flat.map(({product_key,...r})=>r);
   structure=`<p>A flat analytical extract can read descriptions with no joins. It stores 16 copied product-name cells instead of two catalog descriptions. That repetition needs a rebuild or an explicit synchronization rule.</p>${table(rows.slice(0,8),['source_record_id','client_id','product_id','product_name','quantity'],'First eight of the 16 copied rows; selected descriptive columns',r=>state==='anomaly'&&r.source_record_id===D.pharmacy[0].source_record_id?'row-error':'')}`;
   sql=`-- Proposed redundant extract; this table is an illustration.\nSELECT source_record_id, rx_id, line_no, client_id,\n       product_id, product_name, quantity, total_cost\nFROM hdn_flat_dispense_demo\nORDER BY source_record_id;`;
  }else if(mode==='star'){
   rows=D.pharmacy.map(r=>({source_record_id:r.source_record_id,client_id:lookup('clients','client_key',r.client_key).client_id,product_name:catalog.get(r.product_key),quantity:r.quantity,total_cost:r.total_cost}));
   structure=`<div class="normalization-map"><div class="normalized-table"><h4>Event fact</h4><p><code>cb_dtl_ft_pharmacy_dispense</code></p><p><span class="tag">PK</span> <code>dispense_line_key</code><br><span class="tag fk">FK</span> <code>product_key</code><br><span class="tag fk">FK</span> <code>client_key</code></p><p class="hint">Six conformed relationships support the full star; this question needs two.</p></div><div class="normalized-table"><h4>Descriptive context</h4><p><code>cb_dtl_dm_health_product</code></p>${table(D.products.map(p=>({product_key:p.product_key,product_name:catalog.get(p.product_key)})))}<p><code>cb_dtl_dm_client</code> provides the source-facing client ID.</p></div></div><p>The star still uses keys and joins. Grouping descriptive hierarchy attributes in dimensions does not require copying every product name into every fact.</p>`;
   sql=`SELECT f.source_record_id, c.client_id, p.product_name,\n       f.quantity, f.total_cost\nFROM cb_dtl_ft_pharmacy_dispense f\nJOIN cb_dtl_dm_health_product p ON p.product_key = f.product_key\nJOIN cb_dtl_dm_client c ON c.client_key = f.client_key\nORDER BY f.dispense_line_key;`;
  }else{
   rows=D.products.map(p=>{const rs=D.pharmacy.filter(r=>r.product_key===p.product_key);return {product_key:p.product_key,product_name:catalog.get(p.product_key),dispensing_lines:rs.length,total_quantity:sum(rs.map(r=>r.quantity)),known_cost_lines:rs.filter(r=>r.total_cost!==null).length,recorded_cost:stats(rs.map(r=>r.total_cost),'SUM')}});
   structure=`<p>A key-based product summary stores two groups built from 16 detail lines. Its displayed name is joined from the catalog, rather than copied into the stored aggregate. Correcting a product label therefore does not alter its sums; changing a fact measure would require a successful refresh.</p>${table(rows)}<p class="hint">This is a structural row-count comparison, not a measured I/O, storage-size or execution-time benchmark. Quantities remain separate by product.</p>`;
   sql=`-- Proposed summary built with this definition, then joined for labels.\nWITH product_summary AS (\n  SELECT product_key, COUNT(*) AS dispensing_lines,\n         SUM(quantity) AS total_quantity,\n         COUNT(total_cost) AS known_cost_lines,\n         SUM(total_cost) AS recorded_cost\n  FROM cb_dtl_ft_pharmacy_dispense\n  GROUP BY product_key\n)\nSELECT s.product_key, p.product_name, s.dispensing_lines,\n       s.total_quantity, s.known_cost_lines, s.recorded_cost\nFROM product_summary s\nJOIN cb_dtl_dm_health_product p ON p.product_key = s.product_key\nORDER BY s.product_key;\n-- A materialized version stores these groups; the CTE itself does not.`;
  }
  $('.normalization-structure',el).innerHTML=structure;
  $('.normalization-query',el).innerHTML=`<h4>Corresponding Oracle 19c query</h4>${sqlBlock(sql)}${mode==='summary'?'':`<details><summary>Inspect the full ${rows.length}-row illustrative output</summary>${table(rows)}</details>`}<p class="normalization-lab-note">Browser changes affect only this isolated example. The downloaded fixture, source identifiers, foreign keys and Oracle scripts remain unchanged. Fewer joins do not establish a faster plan.</p>`;
 };
 $('.anomaly',el).addEventListener('click',()=>{flat[0].product_name=catalog.get(1)===changedName?changedName+' (one copied edit)':changedName;state='anomaly';$('.normalization-view',el).value='flat';render()});
 $('.catalog-fix',el).addEventListener('click',()=>{catalog.set(1,changedName);flat=makeFlat();state='governed';render()});
 $('.normalization-reset',el).addEventListener('click',()=>{catalog=new Map(originalNames);flat=makeFlat();state='original';$('.normalization-view',el).value='normalized';render()});
 $('.normalization-view',el).addEventListener('change',render);render();
}

function sourceConnectors(){
 const feed=$('.source-feed'),cards=$$('.source-card',feed),target=$('.processing-layers .secure'),svg=$('.source-feed-lines',feed);if(!feed||cards.length!==4||!target||!svg)return;
 let frame;
 const draw=()=>{
  const area=feed.getBoundingClientRect(),to=target.getBoundingClientRect(),rects=cards.map(c=>c.getBoundingClientRect()),bottom=Math.max(...rects.map(r=>r.bottom-area.top)),jx=rects.reduce((sum,r)=>sum+r.left-area.left+r.width/2,0)/4,jy=bottom+28,tx=to.left-area.left+to.width/2,end=to.top-area.top-1;
  svg.setAttribute('viewBox',`0 0 ${area.width} ${area.height}`);
  const branches=rects.map(r=>{const x=r.left-area.left+r.width/2,y=r.bottom-area.top,next=rects.filter(n=>n.top>r.top+3).sort((a,b)=>a.top-b.top)[0];
   const d=next?`M${x} ${y} V${y+(next.top-r.bottom)/2} C${x} ${y+(next.top-r.bottom)/2} ${jx} ${y+(next.top-r.bottom)/2} ${jx} ${next.top-area.top+6} V${jy}`:`M${x} ${y} C${x} ${y+16} ${jx} ${jy-14} ${jx} ${jy}`;
   return `<path class="source-branch" d="${d}"/>`;
  }).join('');
  svg.innerHTML=`${branches}<circle class="source-junction" cx="${jx}" cy="${jy}" r="2.2"/><path class="source-trunk" d="M${jx} ${jy} C${jx} ${jy+18} ${tx} ${end-28} ${tx} ${end-12} V${end}"/><path class="source-arrow" d="M${tx-5} ${end-7} L${tx} ${end} L${tx+5} ${end-7}"/>`;
 };
 const schedule=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(draw)};
 const observer=new ResizeObserver(schedule);observer.observe(feed);observer.observe(target);cards.forEach(c=>observer.observe(c));window.addEventListener('resize',schedule,{passive:true});document.fonts?.ready.then(schedule);draw();
}
function navigation(){
 const preference=window.matchMedia('(prefers-reduced-motion: reduce)');const applyMotion=()=>{document.documentElement.classList.toggle('reduced-motion',preference.matches);if(preference.matches)playerStates.forEach(p=>p.stop())};preference.addEventListener('change',applyMotion);applyMotion();
 const nav=$('#contents'),toggle=$('.nav-toggle');toggle.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open))});
 $('#expand-all').addEventListener('click',()=>$$('nav details',nav).forEach(d=>d.open=true));$('#collapse-all').addEventListener('click',()=>$$('nav details',nav).forEach(d=>d.open=false));
 $$('a[href^="#"]',nav).forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});
 const links=$$('nav a[href^="#"]',nav),targets=links.map(a=>document.getElementById(a.hash.slice(1))).filter(Boolean);
 let scheduled=false;const update=()=>{scheduled=false;let current=targets[0];for(const t of targets){if(t.getBoundingClientRect().top<140)current=t}links.forEach(a=>{if(a.hash===`#${current.id}`)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})};
 const observer=new IntersectionObserver(()=>update(),{rootMargin:'-70px 0px -65% 0px',threshold:0});targets.forEach(t=>observer.observe(t));window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update)}},{passive:true});update();
}
